import openpyxl, os
src='/root/data/workbook.xlsx'
dst='/root/output/result.xlsx'
wb0=openpyxl.load_workbook(src, data_only=False)
wb=openpyxl.load_workbook(dst, data_only=False)
style_id_changes=[]
for s in wb0.sheetnames:
    ws0=wb0[s]; ws=wb[s]
    for r in range(1, max(ws0.max_row, ws.max_row)+1):
        for c in range(1, max(ws0.max_column, ws.max_column)+1):
            if ws0.cell(r,c).style_id != ws.cell(r,c).style_id:
                style_id_changes.append((s, ws.cell(r,c).coordinate, ws0.cell(r,c).style_id, ws.cell(r,c).style_id))
print('style_id changes:', len(style_id_changes))
# Column widths / row heights / merged cells unchanged?
layout_changes=[]
for s in wb0.sheetnames:
    ws0=wb0[s]; ws=wb[s]
    if sorted(str(x) for x in ws0.merged_cells.ranges) != sorted(str(x) for x in ws.merged_cells.ranges):
        layout_changes.append((s,'merged_cells'))
    cols=set(ws0.column_dimensions.keys()) | set(ws.column_dimensions.keys())
    for col in cols:
        d0=ws0.column_dimensions[col]; d=ws.column_dimensions[col]
        if (d0.width,d0.hidden,d0.outlineLevel) != (d.width,d.hidden,d.outlineLevel):
            layout_changes.append((s,'col',col,(d0.width,d0.hidden,d0.outlineLevel),(d.width,d.hidden,d.outlineLevel)))
    rows=set(ws0.row_dimensions.keys()) | set(ws.row_dimensions.keys())
    for row in rows:
        d0=ws0.row_dimensions[row]; d=ws.row_dimensions[row]
        if (d0.height,d0.hidden,d0.outlineLevel) != (d.height,d.hidden,d.outlineLevel):
            layout_changes.append((s,'row',row,(d0.height,d0.hidden,d0.outlineLevel),(d.height,d.hidden,d.outlineLevel)))
print('layout changes:', len(layout_changes))
for x in style_id_changes[:10]+layout_changes[:10]: print(x)
